  if
  (
    byte == 60U && st.offset == base.range.last &&
      (TmtParser_can_assign(base.target) || base.target == TmtParser_OptionalChain)
  )
    generic = TmtParser_call_type_arguments(input, st);
  else
    generic = TmtParser_failed(st, 1U);
